export const ATTORNEY_REVIEW = [{"item":"R.A. 9485 \"repealed\" by R.A. 11032 (titles 245, 275, 315, 430, 452, 456, 459, 462, 463, 507, 508, 512)","verdict":"partly","finding":"R.A. 11032 Sec. 1 amends Sec. 1 of R.A. 9485 and renames it the Ease of Doing Business and Efficient Government Service Delivery Act of 2018. It amends and renumbers the old act. It does not repeal it. Sec. 6 (Citizens Charter) keeps its number. Old Sec. 10 (Report Card Survey) is now Sec. 20 under R.A. 11032 Sec. 12. Counsel was right that the bare R.A. 9485 cite had to change, and right to doubt that the Report Card Survey was still Sec. 10.","action":"All 12 titles now cite R.A. 9485 as amended by R.A. 11032: Sec. 6 for the Citizens Charter and Sec. 20 for the Report Card Survey.","laws":["11032"]},{"item":"R.A. 7160 Sec. 458 as the only basis (traffic, tricycle, street, ordinance titles)","verdict":"accepted","finding":"Sec. 458 covers the whole Sangguniang Panlungsod. Each title now names the exact paragraph: 458(a)(5)(vi) regulate traffic, 458(a)(3)(vi) tricycles under DOTC guidelines, 458(a)(5)(v) streets and street lighting, 458(a)(2)(ix) zoning. Where R.A. 4136 fits, it is added: Sec. 35 speed, Sec. 46 parking, Sec. 55 duty after an accident. Ordinance titles now cite Sec. 59, which requires ordinances to be posted.","action":"23 titles re-anchored. Streetlight titles 171 and 503 move to the City Engineer (Sec. 477, public works).","laws":["7160","4136"]},{"item":"R.A. 10121 Sec. 12(c)(23) and (c)(5) are \"phantom subsections\" (titles 49, 433, 436, 455)","verdict":"rejected","finding":"Sec. 12(c) lists 25 numbered LDRRMO functions. Item (5) is \"Operate a multi-hazard early warning system\". Item (23) is \"Establish a Provincial/City/Municipal/Barangay Disaster Risk Reduction and Management Operations Center\". Both pinpoints match.","action":"Cites kept. The verbatim quote is shown on each card so a panel can check it.","laws":["10121"]},{"item":"R.A. 10121 Sec. 12 is the Council, not the Office","verdict":"rejected","finding":"Sec. 11 is \"Organization at the Local Government Level\" (the councils). Sec. 12 is \"Local Disaster Risk Reduction and Management Office (LDRRMO)\".","action":"No change.","laws":["10121"]},{"item":"R.A. 8435 Sec. 41 is not the National Information Network (titles 83, 100)","verdict":"rejected","finding":"Sec. 41 of R.A. 8435 is headed \"National Information Network\" and sets up the NIN from the Department down to municipal offices.","action":"No change.","laws":["8435"]},{"item":"R.A. 9710 Sec. 13 is not the education provision (title 438)","verdict":"rejected","finding":"Sec. 13 of R.A. 9710 is \"Equal Access and Elimination of Discrimination in Education, Scholarships, and Training\".","action":"No change.","laws":["9710"]},{"item":"R.A. 9710 Sec. 33 does not cover seniors (title 255)","verdict":"partly","finding":"Sec. 33 is \"Protection of Senior Citizens\", so the cite exists. Counsel was right that the main senior statute should also appear.","action":"Added R.A. 7432 Sec. 6 as amended by R.A. 9994 (OSCA) and R.A. 10173 Sec. 13.","laws":["9710","9994"]},{"item":"Untitled or garbled headings: R.A. 10754 Sec. 32, R.A. 9994 Secs. 4 and 6, R.A. 8485 Sec. 6, R.A. 11898 Sec. 5, R.A. 11285 Sec. 15, R.A. 11332 Sec. 8, R.A. 11053 Sec. 6","verdict":"accepted","finding":"These were scraper artefacts. R.A. 10754 Sec. 1 rewrites R.A. 7277 Sec. 32, which grants the 20% discount and VAT exemption. R.A. 9994 rewrites R.A. 7432 Secs. 4 and 6. R.A. 8485 Sec. 6 has no heading. The headings for R.A. 11285 Sec. 15 and R.A. 11332 Sec. 8 were cut at a line break.","action":"Every caption now names the base act, the amending act and the full heading.","laws":["10754","9994","11285","11332"]},{"item":"Social pension titles 230 and 247 should cite the benefit itself","verdict":"accepted","finding":"R.A. 7432 Sec. 4(h)(1) as amended by R.A. 9994 grants indigent seniors a monthly social pension.","action":"Title 247 cites Sec. 4 as amended. Title 230 keeps OSCA (Sec. 6) as the operating office.","laws":["9994"]},{"item":"R.A. 10152: immunization reminders should cite Secs. 3 and 4, not Sec. 5 (title 192)","verdict":"accepted","finding":"Sec. 3 lists the covered vaccine-preventable diseases. Sec. 4 sets the education and information campaign. Sec. 5 is the duty to inform before delivery, which fits title 509 better.","action":"Title 192 cites Secs. 3 and 4 plus R.A. 10173 Sec. 13. Title 509 adds Sec. 4.","laws":["10152"]},{"item":"R.A. 7877 replaced by R.A. 11313 (title 253)","verdict":"partly","finding":"R.A. 11313 Sec. 40 repeals only laws \"contrary to or inconsistent with\" it, and it never names R.A. 7877. Both stay in force. R.A. 11313 Sec. 21 requires schools to designate an officer for gender-based sexual harassment complaints.","action":"Title 253 cites both acts.","laws":["7877","11313"]},{"item":"R.A. 7277 Sec. 22 (Broadcast Media) does not support app localization (title 464)","verdict":"accepted","finding":"Sec. 22 asks TV stations for sign-language insets or subtitles. It is about broadcasts, not software language.","action":"Re-anchored to 1987 Constitution Art. XIV Sec. 6 and R.A. 7104 Sec. 14 (Commission on the Filipino Language).","laws":["consti","7104"]},{"item":"Central Business Portal does not cover barangay clearance or building permits (titles 283, 314)","verdict":"accepted","finding":"R.A. 11032 Sec. 13 covers business permit processing.","action":"Title 283 now cites R.A. 7160 Sec. 152(c) (Barangay Clearance). Title 314 cites Sec. 477 (the city engineer is the local building official) and a P.D. 1096 pointer. Lawphil returned 404 for P.D. 1096, so its section is not confirmed.","laws":["7160"]},{"item":"Information request tracker needs a right-to-information basis (titles 39, 285)","verdict":"accepted","finding":"Art. III Sec. 7 recognizes the right to information on matters of public concern. E.O. No. 2, s. 2016 Sec. 2 covers the executive branch and says LGUs are \"encouraged\" to follow it. It does not bind Lipa.","action":"Both titles add Art. III Sec. 7. Title 285 adds E.O. 2 with that limit stated.","laws":["consti","eo2"]},{"item":"R.A. 12027 \"discontinues\" the mother tongue (title 373)","verdict":"accepted","finding":"The enrolled title on Lawphil reads \"An Act Discounting the Use of the Mother Tongue\". The intent is discontinuing.","action":"The caption quotes the enrolled word and states the meaning.","laws":["12027"]},{"item":"Partners: WCPD is a PNP unit; hydrants need the water district; LPG needs BFP and DTI/DOE; SEF needs the Local School Board; SK fund needs the SK Federation","verdict":"accepted","finding":"Counsel was right that these partners were mismatched. R.A. 11592 Sec. 12 lets LGUs suspend LPG business permits on DOE action. R.A. 7160 Secs. 98 and 99 create the Local School Board, which handles the Special Education Fund budget.","action":"Partners changed on titles 52, 53, 249, 269, 312, 317 and 320. OSCA, PESO, tourism and youth offices carry a fallback and a confirm flag.","laws":["11592","7160"]},{"item":"Privacy overlay for titles that touch personal or health data","verdict":"accepted","finding":"Counsel listed about 50 titles. Each now leads with R.A. 10173 Sec. 11 (principles) or Sec. 13 (sensitive personal information) before any security section.","action":"35 titles gained a DPA anchor. Health, child, senior and civil registry titles use Sec. 13.","laws":["10173"]},{"item":"Counsel memory note: DPA Sec. 20 is the Data Privacy Officer provision","verdict":"rejected","finding":"Counsel caught this one in their own notes. Sec. 20 of R.A. 10173 is \"Security of Personal Information\".","action":"No change. The cites already used Sec. 20 for security.","laws":["10173"]},{"item":"Institutional-only titles need a stated basis (32 titles)","verdict":"accepted","finding":"Silence invites a panel question. A statute is not required for empirical research topics.","action":"Each is labelled \"Institutional basis\" and points to CHED CMO 25 s.2015 and the STI capstone guideline.","laws":[]},{"item":"Research-heavy scope for BSIT (18 titles)","verdict":"accepted","finding":"Counsel judged these too large for two terms.","action":"Each card adds a BSIT cut: build capture, storage and dashboard first; keep modelling or field trials for the MSIT extension. Verdict moves to Revise.","laws":[]},{"item":"Weak or stretched bases (titles 167, 181, 323, 348, 389, 390)","verdict":"accepted","finding":"The laws support the policy area, not the specific feature.","action":"Each card now says \"policy support only\" and the verdict is Revise.","laws":[]},{"item":"Duplicates and near-duplicates (23, 173/187, 325/326, site overlaps 51, 421, 436)","verdict":"accepted","finding":"Title 187 repeats 173. Title 23 sat close to an existing site title. Titles 325 and 326 overlapped.","action":"187 merges into 173. Titles 23 and 326 are retitled. Overlap notes on 51, 421 and 436 say how they differ.","laws":[]},{"item":"Title fixes: 199 add partner, 396 teaching allowance is for teachers, 403 scanning needs written authorization","verdict":"accepted","finding":"R.A. 11997 Sec. 4 grants the Teaching Allowance to public school teachers. Scanning without authorization can be illegal access under R.A. 10175 Sec. 4(a)(1).","action":"Titles 199, 396 and 403 rewritten.","laws":["11997","10175"]},{"item":"Regulatory pointers: NTC (63), CAAP (64), DepEd (67, 389), PAGASA/DOLE (56), PDNA (51, 79), DOH TB (197), WHO growth (200), NPC 16-03 (307)","verdict":"accepted","finding":"These are rules outside the cited acts. We did not open them in this review.","action":"Added as notes and marked not opened.","laws":[]},{"item":"Every remaining \"verify\" pinpoint (UHC, Mental Health, Magna Carta PWD, heritage, housing, tourism, SIM, free internet)","verdict":"accepted","finding":"We re-opened all 143 source texts on Lawphil on 2026-10-13. Every cited section was found, and the matched keyword appears inside that section or sub-paragraph.","action":"Each card shows the matched text verbatim with a Lawphil link.","laws":[]}];
